function CommRoleBonusLayoutGroupCell:RefreshUI(data, curStar, isShowLine)
	CfUtils.SetActive(self.ImgLine, isShowLine)
	if curStar == -1 then
		CfUtils.SetUISwitchImage(self.ImgStar,1)
		CfUtils.SetUISwitchText(self.TxtNum,1)
		CfUtils.SetUISwitchText(self.TxtDesc,1)
	else
		local state = curStar == checkNumber(data.target) and 2 or 1
		CfUtils.SetUISwitchImage(self.ImgStar,state)
		CfUtils.SetUISwitchText(self.TxtNum,state)
		CfUtils.SetUISwitchText(self.TxtDesc,state)
	end
	CfUtils.FillText(self.TxtNum,data.target)
	local vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(data.commonAddId)
	if vo then
		CfUtils.FillText(self.TxtDesc, vo.desc)
	end
end

function CommRoleBonusLayoutGroupCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return CommRoleBonusLayoutGroupCell